package net.civeira.phylax.features.access.useracceptedtermsofuse.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.access.useracceptedtermsofuse.domain.UserAcceptedTermsOfUse;
import net.civeira.phylax.features.access.useracceptedtermsofuse.domain.event.UserAcceptedTermsOfUseEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class UserAcceptedTermsOfUseEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<UserAcceptedTermsOfUseEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final UserAcceptedTermsOfUse entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
